 public Snapshot inspect(String expectedHostHead,boolean allowPending)throws IOException{guard();if(!index.exists()){if(!"ROOT".equals(expectedHostHead)||dir.exists()||child(ARCHIVES).exists())throw bad("INDEX_MISSING_NOT_FRESH");return new Snapshot(new State(),false);}State s=state(true);boolean anchored=anchor(s,expectedHostHead);if((s.pending!=null||requestPending(s))&&!allowPending)throw bad("PENDING_NO_AUTOMATIC_REPLAY");physical(s,true,allowPending);return new Snapshot(s,anchored);}
