 public RequestTicket reserveRequest(String nonce,String operation)throws IOException{writable();if(nonce==null||!nonce.matches("[a-f0-9]{32}")||!Arrays.asList("PREVIEW","APPLY","RECOVER").contains(operation))throw bad("REQUEST_SCOPE");State s=state(false);if(!s.enrolled)throw bad("ENROLLMENT_REQUIRED");Request old=s.requests.get(nonce);if(old!=null){if(!old.operation.equals(operation)||old.committed)throw bad("REQUEST_NONCE_REPLAY_OR_OPERATION");physical(s,true,true);return new RequestTicket(files,old);}if(s.pending!=null&&(!s.pending.type.equals("ARCHIVE_BEGIN")||!operation.equals("RECOVER")))throw bad("REQUEST_NATIVE_PENDING");boolean implicit=s.initialRequestUnbound;if(implicit){if(!operation.equals("APPLY")||s.rq!=1||!s.requests.isEmpty())throw bad("INITIAL_REQUEST_APPLY_BINDING");}else if(requestPending(s)||s.rq>=32)throw bad("REQUEST32_OR_UNKNOWN_PENDING");physical(s,true,true);reserveTransition(4096);append(s,"REQUEST_RESERVE",fields(nonce,operation,implicit?"1":"0"));return new RequestTicket(files,s.requests.get(nonce));}
