 public Ticket beginArchive(String planSHA256,String expectedHostHead,List<Original> oo)throws IOException{writable();if(oo==null||oo.isEmpty()||oo.size()>8)throw bad("ARCHIVE_MEMBERS8");hash(planSHA256);State s=state(false);anchor(s,expectedHostHead);List<String> f=fields(planSHA256,Integer.toString(oo.size()));for(Original o:oo)addOriginal(f,o);if(s.pending!=null){if(s.pending.type.equals("ARCHIVE_BEGIN")&&s.pending.f.equals(f)){physical(s,true,true);return new Ticket(files,s.pending);}throw bad("FOREIGN_PENDING_NO_REPLAY");}pending(s);if(oo==null||oo.isEmpty()||oo.size()>8||s.ra>=8||s.batches.containsKey(planSHA256))throw bad("ARCHIVE_RESERVATION_BOUND");Set<String> unique=new HashSet<>();for(Original o:oo){Member m=require(s,o.generation);if(!unique.add(o.generation)||!m.closed||!m.location.startsWith(ACTIVE+"/")||!m.disposition.equals(o.disposition)||m.bytes!=o.bytes||!Objects.equals(m.sha,o.sha256)||m.outcome||m.disposition.equals("UNRESOLVED"))throw bad("ARCHIVE_MEMBER_HIGHWATER");}physical(s,true,false);for(Original o:oo){Member m=require(s,o.generation);if(!fullSHA(child(m.location),m.bytes).equals(o.sha256))throw bad("ARCHIVE_ORIGINAL_SHA");}reserveTransition(0);append(s,"ARCHIVE_BEGIN",f);return new Ticket(files,s.pending);}
